package service
import("context";"testing";"github.com/11DingKing/vocational-admission-go/internal/domain")
func TestDecisionAuditFailureKeepsReviewState(t *testing.T){s,db,pid,gid:=svc(t);a,e:=s.Submit(context.Background(),domain.Application{PlanID:pid,MajorGroupID:gid,StudentNo:"20265001",Score:600,Rank:1,IdempotencyKey:"dec"},1,"r");if e!=nil{t.Fatal(e)};if e=s.Decide(context.Background(),a.ID,domain.ApplicationReviewing,"review",2,"r2");e!=nil{t.Fatal(e)};if _,e=db.SQL.Exec("CREATE TRIGGER fail_decision_audit BEFORE INSERT ON decisions BEGIN SELECT RAISE(ABORT,'audit down'); END");e!=nil{t.Fatal(e)};if e=s.Admit(context.Background(),a.ID,2,"r3");e==nil{t.Fatal("expected audit failure")};got,e:=s.Apps.ByID(context.Background(),a.ID);if e!=nil{t.Fatal(e)};if got.Status!=domain.ApplicationReviewing{t.Fatalf("status committed despite audit failure: %s",got.Status)}}
